public void insert()
{
    XML request = this.RequestXML;
    XML answer = this.AnswerXML;
    XML result = this.ResultXML;

    this.RequestXML = '';
    this.AnswerXML = '';
    this.ResultXML = '';
    super();
    if (request)
    {
        TFMXMLTable::StoreXML(request,this,fieldStr(TFMDocumentQueue,RequestXML));
        TFMXMLTable::StoreXML(request,this,fieldStr(TFMDocumentQueue,RequestXMLOriginal));
    }
    if (answer)
    {
        TFMXMLTable::StoreXML(answer,this,fieldStr(TFMDocumentQueue,AnswerXML));

    }
    if (result)
    {
        TFMXMLTable::StoreXML(result,this,fieldStr(TFMDocumentQueue,ResultXML));

    }

    // Telemetry logging
    this.logTelemetry();
}

public void update()
{
    XML request = this.RequestXML;
    XML answer = this.AnswerXML;
    XML result = this.ResultXML;

    this.RequestXML = '';
    this.AnswerXML = '';
    this.ResultXML = '';
    super();
    if (request)
    {
        TFMXMLTable::StoreXML(request,this,fieldStr(TFMDocumentQueue,RequestXML));

    }
    if (answer)
    {
        TFMXMLTable::StoreXML(answer,this,fieldStr(TFMDocumentQueue,AnswerXML));

    }
    if (result)
    {
        TFMXMLTable::StoreXML(result,this,fieldStr(TFMDocumentQueue,ResultXML));

    }

    // Telemetry logging
    this.logTelemetry();
}

/// <summary>
/// Log telemetry for document queue processing
/// </summary>
protected void logTelemetry()
{
    if(this.Status == TFMDocumentQueueStatus::Completed ||
       this.Status == TFMDocumentQueueStatus::Error)
    {   
        TFMAppInsightsDocQueueTelemetry docQueueTelemetry = TFMAppInsightsDocQueueTelemetry::newFromDocumentQueue(this);
        TFMAppInsightsTelemetryLogger::instance().trackDocQueue(docQueueTelemetry);
    }
}

public void resetStatus()
{
    if (this.Status == TFMDocumentQueueStatus::Processing)
    {
        ttsbegin;
        this.Status = TFMDocumentQueueStatus::ReadyForProcessing;
        if (this.validateWrite())
        {
            this.update();
        }
        ttscommit;
    }
}

	/// <summary>
	/// Method to find a Queue entry from a Message ID.
	/// </summary>
	/// <param name = "_messageId">Unique Message ID to find message by. Is a GUID.</param>
	/// <param name = "_forUpdate">Should the record be selected for update?</param>
	/// <returns>Found TFMDocumentQueue record</returns>
    public static TFMDocumentQueue find(TFMDocumentMessageId _messageId, boolean _forUpdate = false)
    {
        TFMDocumentQueue    queue;
        ;
        if (_messageId)
        {
            if (_forUpdate)
            {
                queue.selectForUpdate(_forUpdate);
            }
            select firstonly queue
                index hint MessageIdIdx
                where queue.MessageId == _messageId;
        }

        return queue;
    }

	/// <summary>
    /// Method to set error message on incoming document
    /// </summary>
    /// <param name = "_messageId">Message ID of the incoming document.</param>
    /// <param name = "_returnStr">The error message to be written on the document.</param>
    /// <returns>The resulting error XML</returns>
    public static TFMDocumentXML updateStatusError(TFMDocumentMessageId _messageId, TFMDocumentXML _returnStr)
    {
        TFMDocumentQueue                documentQueue;
        //UserConnection                  connection;


        ttsBegin;
        documentQueue                = TFMDocumentQueue::find(_messageId,true);
        documentQueue.Status         = TFMDocumentQueueStatus::Error;
        documentQueue.AnswerXML      = TFMDocumentConnector::createReturnXml(_returnStr, '', documentQueue.MessageId, TFMDocumentQueueStatus::Error);
        documentQueue.ResultXML      = documentQueue.AnswerXML;
        documentQueue.AnswerDateTime = DateTimeUtil::getSystemDateTime();

        documentQueue.update();
        ttsCommit;

        return documentQueue.AnswerXML();
    }

public XML AnswerXML()
{
    return this.AnswerXML ? this.AnswerXML : TFMXMLTable::getXML(this,fieldStr(TFMDocumentQueue,AnswerXML));
}

public XML RequestXML()
{
    return this.RequestXML ? this.RequestXML : TFMXMLTable::getXML(this,fieldStr(TFMDocumentQueue,RequestXML));
}

public XML RequestXMLOriginal()
{
    return this.RequestXMLOriginal ? this.RequestXMLOriginal : TFMXMLTable::getXML(this,fieldStr(TFMDocumentQueue,RequestXMLOriginal));
}

public XML ResultXML()
{
    return this.ResultXML ? this.ResultXML : TFMXMLTable::getXML(this,fieldStr(TFMDocumentQueue,ResultXML));
}

public void jumpToMainTable()
{
    SysDictTable dt = new SysDictTable(this.refTableId);
    Common			common = dt.makeRecord();
    str formRef = dt.formRef();
    Args args = new Args();
    FormRun		formRun;
    select firstonly common where common.RecId == this.refRecId;

    args.record(common);
    args.name(formRef);
    formRun = classfactory.formRunClass(args);
    formRun.init();
    formRun.run();

    formRun.wait();
}

public str getHtmlMessage()
{
    XmlDocument xmlDoc = XmlDocument::newXml(this.AnswerXML());
    XmlElement	response = xmlDoc.getNamedElement('response');
    XmlElement	description,responseData,image;
    str			startText	= 'src="data:image/';
    str			endText		= '" alt="';
    str			resNameEnd	= '" />';
    str			htmlText;
    int			posStart, posEnd, resEnd;
    str			resName;
    str			errorTxt;

    if (response && this.DocumentType == methodStr(TFMDocGetMedia,GetMedia) && this.Status == TFMDocumentQueueStatus::Completed)
    {
        responseData = response.getNamedElement('responseData');
        image = responseData.getNamedElement('media').getNamedElement('image');
        return TFMImageHelper::base64ToHtml(image.innerText(), 170, image.getAttribute('id'));
    }
    else if (response)
    {
        description = response.getNamedElement('description');
        htmlText = description ? description.innerText() : '';
        posStart = 1;
        while (posStart)
        {
            posStart	= strScan(htmlText,startText,1,strLen(htmlText));
            posEnd		= strScan(htmlText,endText,posStart,strLen(htmlText));
            resEnd		= strScan(htmlText,resNameEnd,posEnd,strLen(htmlText));
            if (posStart)
            {
                resName		= subStr(htmlText,posEnd + strLen(endText),resEnd-posEnd - strLen(endText));
                if (!SysResource::checkIfResourceExists(resName))
                {
                    resName = resourceStr(TFMPaperHole);
                }
                htmlText	= subStr(htmlText,1,posStart-1) +'src="'+ SysResource::getImagePath(resName) +  subStr(htmlText,posEnd,strLen(htmlText));
            }
        }
        if (!strScan(htmlText,'<html>',1,10000))
        {
            //htmlText = '<pre>'+ htmlText + '</pre>';
            htmlText = strReplace(strReplace(htmlText,' ' , '&nbsp;'),'\n','<br>');
        }
    }

    /*if (this.Status == TFMDocumentQueueStatus::Error)
    {
        errorTxt = con2Str(this.CallStack, ';');
        if (!strScan(htmlText,'<html>',1,10000))
        {
            htmlText += errorTxt;
        }
        else
        {
            htmlText = strReplace(htmlText, '</html>',errorTxt + '</html>');
        }
    }*/
    return htmlText;
}
